// Builds the subject and HTML for one notification row from lamig.claim_due_notifications().
const n = $input.item.json;
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const peso = 'PHP ' + Number(n.price_php).toLocaleString('en-PH', { maximumFractionDigits: 0 });
const first = String(n.customer_name || '').split(' ')[0] || 'there';

const copy = {
  confirmation: {
    subject: `Booked: ${n.service_name}, ${n.when_label} (${n.ref})`,
    heading: "You're booked",
    intro: `Hi ${first}, thanks for booking with ${n.business_name}. Here are your details.`,
    outro: 'Please clear the area around the unit and have someone 18 or older at home. Need to change something? Reply to this email or chat with us on the website, and mention your booking reference.',
  },
  reminder: {
    subject: `Reminder: aircon cleaning ${n.when_label}`,
    heading: 'See you soon',
    intro: `Hi ${first}, this is a reminder that our crew is coming for your aircon cleaning.`,
    outro: `Can't make it? Let us know as soon as you can by calling ${n.business_phone}.`,
  },
  follow_up: {
    subject: 'How is your aircon running?',
    heading: 'How did we do?',
    intro: `Hi ${first}, thanks for choosing ${n.business_name}. We hope your aircon is cold again.`,
    outro: `If the unit leaks or has any problem caused by our work, we fix it for free within 7 days. Call or text ${n.business_phone} and mention ${n.ref}.`,
  },
}[n.kind];

if (!copy) throw new Error('Unknown notification kind: ' + n.kind);

const row = (label, value) => `<tr><td style="padding:6px 16px 6px 0;color:#4f6b78;vertical-align:top">${label}</td><td style="padding:6px 0;font-weight:bold;color:#10303b">${esc(value)}</td></tr>`;

const html = `<!doctype html><html><body style="margin:0;background:#eef4f7;font-family:Arial,Helvetica,sans-serif;color:#10303b">
<div style="max-width:560px;margin:0 auto;padding:24px 16px">
  <div style="background:#10303b;color:#eef4f7;border-radius:20px;padding:24px">
    <p style="margin:0;font-size:22px;font-weight:bold">${esc(copy.heading)}</p>
    <p style="margin:12px 0 0;font-size:32px;font-weight:bold;color:#f2b33d;letter-spacing:1px">${esc(n.ref)}</p>
    <p style="margin:2px 0 0;color:#c3d6df;font-size:13px">Booking reference</p>
  </div>
  <div style="background:#ffffff;border-radius:20px;padding:24px;margin-top:12px;font-size:15px;line-height:1.5">
    <p style="margin:0 0 16px">${esc(copy.intro)}</p>
    <table style="border-collapse:collapse;font-size:15px">
      ${row('Service', n.service_name)}
      ${row('When', n.when_label)}
      ${row('Address', n.address)}
      ${row('Price', peso + ', pay after the job (cash or GCash)')}
    </table>
    <p style="margin:16px 0 0">${esc(copy.outro)}</p>
  </div>
  <p style="color:#4f6b78;font-size:12px;margin:16px 4px 0">${esc(n.business_name)}, ${esc(n.business_phone)}. This is a demo business for an AI automation project.</p>
</div></body></html>`;

return {
  json: {
    notification_id: n.notification_id,
    to_email: n.to_email,
    subject: copy.subject,
    html,
  },
};
